/* ===== CSS Custom Properties ===== */
:root {
  --green-primary: #00824A;
  --green-dark: #32462F;
  --green-light: #1A8F5C;
  --green-pale: #E8F5EE;
  --cream: #F3CEA1;
  --cream-light: #FDF3E7;
  --cream-dark: #D4A86A;
  --white: #FFFFFF;
  --off-white: #FAFAF7;
  --gray-50: #F7F7F5;
  --gray-100: #EDEDEA;
  --gray-200: #D4D4D0;
  --gray-300: #B0B0AA;
  --gray-400: #8A8A84;
  --gray-500: #63635E;
  --gray-600: #4A4A46;
  --gray-700: #363632;
  --gray-800: #242420;
  --gray-900: #141410;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.1), 0 4px 8px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 48px rgba(0,0,0,0.12), 0 8px 16px rgba(0,0,0,0.04);
  --font-body: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --max-width: 1280px;
  --header-height: 72px;
}

/* ===== Reset ===== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background-color: var(--white);
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--gray-900);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 3.5vw, 2.75rem); }
h3 { font-size: clamp(1.5rem, 2.5vw, 2rem); }
h4 { font-size: 1.25rem; }

/* ===== Utility Classes ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 80px 0;
}

.section-label {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--green-primary);
  margin-bottom: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.95rem;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.btn-primary {
  background: var(--green-primary);
  color: var(--white);
}
.btn-primary:hover {
  background: var(--green-light);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  border: 2px solid var(--green-primary);
  color: var(--green-primary);
  background: transparent;
}
.btn-outline:hover {
  background: var(--green-primary);
  color: var(--white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline-light {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn-outline-light:hover {
  background: var(--white);
  color: var(--green-dark);
}

.btn-cream {
  background: var(--cream);
  color: var(--green-dark);
}
.btn-cream:hover {
  background: var(--cream-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

/* ===== Header / Navigation ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-100);
  height: var(--header-height);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--green-primary);
}

.logo i {
  font-size: 1.6rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-links a {
  padding: 8px 16px;
  border-radius: var(--radius-full);
  font-weight: 500;
  font-size: 0.9rem;
  color: var(--gray-700);
  transition: all 0.2s;
}

.nav-links a:hover,
.nav-links a.active {
  background: var(--green-pale);
  color: var(--green-primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-actions .btn {
  padding: 8px 20px;
  font-size: 0.85rem;
}

.mobile-menu-btn {
  display: none;
  font-size: 1.5rem;
  color: var(--gray-800);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 99;
  padding: 24px;
  flex-direction: column;
  gap: 8px;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  padding: 12px 16px;
  font-size: 1.1rem;
  font-weight: 500;
  border-radius: var(--radius-md);
  color: var(--gray-800);
}
.mobile-nav a:hover,
.mobile-nav a.active {
  background: var(--green-pale);
  color: var(--green-primary);
}

.mobile-nav .nav-actions {
  margin-top: 16px;
  flex-direction: column;
}

/* ===== Hero ===== */
.hero {
  position: relative;
  background: linear-gradient(135deg, var(--green-dark) 0%, #1A3A2A 50%, var(--green-dark) 100%);
  color: var(--white);
  padding: 100px 0;
  overflow: hidden;
  min-height: 560px;
  display: flex;
  align-items: center;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 80%;
  height: 200%;
  background: radial-gradient(ellipse, rgba(0,130,74,0.15) 0%, transparent 70%);
}

.hero .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  position: relative;
  z-index: 1;
}

.hero-content h1 {
  color: var(--white);
  font-size: clamp(2.8rem, 5vw, 4.5rem);
  line-height: 1.1;
  margin-bottom: 24px;
}

.hero-content .btn {
  padding: 16px 36px;
  font-size: 1.05rem;
}

.hero-image {
  background: linear-gradient(135deg, rgba(243,206,161,0.2), rgba(0,130,74,0.2));
  border-radius: var(--radius-xl);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
  color: rgba(255,255,255,0.3);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.1);
}

/* ===== Featured Product Card ===== */
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.featured-card-image {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--cream), var(--cream-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  color: var(--green-dark);
}

.featured-card-content {
  padding: 48px 48px 48px 0;
}

.featured-card-content h2 {
  margin-bottom: 12px;
}

.featured-card-content p {
  color: var(--gray-600);
  margin-bottom: 24px;
  font-size: 1.05rem;
}

/* ===== Promo Cards ===== */
.promo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.promo-card {
  position: relative;
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  overflow: hidden;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.promo-card::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 50%;
  height: 160%;
  background: radial-gradient(ellipse, rgba(255,255,255,0.08) 0%, transparent 70%);
}

.promo-card.cream-bg {
  background: var(--cream-light);
  color: var(--gray-800);
}

.promo-card.cream-bg h2 {
  color: var(--green-dark);
}

.promo-card > * {
  position: relative;
  z-index: 1;
}

.promo-card h2 {
  color: var(--white);
  margin-bottom: 12px;
  font-size: clamp(1.5rem, 2.5vw, 2rem);
}

.promo-card p {
  color: rgba(255,255,255,0.8);
  margin-bottom: 20px;
  font-size: 1rem;
  max-width: 400px;
}

.promo-card.cream-bg p {
  color: var(--gray-600);
}

/* ===== Seasonal Highlight ===== */
.seasonal-highlight {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.seasonal-highlight.reverse {
  direction: rtl;
}

.seasonal-highlight.reverse .highlight-content {
  direction: ltr;
}

.highlight-image {
  aspect-ratio: 4/3;
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, #FDF3E7, #E8F5EE);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  color: var(--green-primary);
}

.highlight-content h2 {
  margin-bottom: 12px;
}

.highlight-content p {
  color: var(--gray-600);
  margin-bottom: 24px;
  font-size: 1.05rem;
}

/* ===== Nondairy Promo ===== */
.promo-banner {
  background: var(--green-pale);
  border-radius: var(--radius-xl);
  padding: 48px;
  text-align: center;
}

.promo-banner h2 {
  color: var(--green-dark);
  margin-bottom: 8px;
}

.promo-banner p {
  color: var(--gray-600);
  margin-bottom: 24px;
  font-size: 1.05rem;
}

/* ===== Page Hero (non-home) ===== */
.page-hero {
  background: linear-gradient(135deg, var(--green-dark), #1A3A2A);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 50%;
  height: 160%;
  background: radial-gradient(ellipse, rgba(0,130,74,0.2) 0%, transparent 70%);
}

.page-hero > * {
  position: relative;
  z-index: 1;
}

.page-hero h1 {
  color: var(--white);
  margin-bottom: 16px;
}

.page-hero p {
  color: rgba(255,255,255,0.85);
  font-size: 1.15rem;
  max-width: 600px;
  margin: 0 auto 24px;
}

/* ===== Breadcrumb ===== */
.breadcrumb {
  padding: 16px 0;
  font-size: 0.85rem;
  color: var(--gray-400);
}

.breadcrumb a {
  color: var(--gray-500);
}
.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb span {
  margin: 0 8px;
}

/* ===== Menu Layout ===== */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 48px;
  align-items: start;
}

.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + 24px);
}

.menu-sidebar h3 {
  font-family: var(--font-body);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--gray-400);
  margin-bottom: 4px;
  margin-top: 20px;
}

.menu-sidebar h3:first-child {
  margin-top: 0;
}

.menu-sidebar a {
  display: block;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  color: var(--gray-700);
  transition: all 0.15s;
}

.menu-sidebar a:hover,
.menu-sidebar a.active {
  background: var(--green-pale);
  color: var(--green-primary);
  font-weight: 600;
}

.menu-main h2 {
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--gray-100);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
}

.menu-item {
  display: flex;
  gap: 16px;
  padding: 16px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  transition: all 0.2s;
}

.menu-item:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-md);
}

.menu-item-image {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  background: var(--gray-50);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: var(--green-primary);
}

.menu-item-info h4 {
  margin-bottom: 4px;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.95rem;
}

.menu-item-info p {
  font-size: 0.8rem;
  color: var(--gray-500);
  line-height: 1.4;
}

/* ===== Rewards ===== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green-primary), var(--green-dark));
  text-align: center;
  padding: 80px 0;
  color: var(--white);
  border-radius: var(--radius-xl);
  margin-bottom: 48px;
}

.rewards-hero h1 {
  color: var(--white);
  margin-bottom: 16px;
}

.rewards-hero p {
  color: rgba(255,255,255,0.85);
  font-size: 1.1rem;
  max-width: 600px;
  margin: 0 auto 24px;
}

/* How It Works */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.step-card {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--radius-lg);
  background: var(--off-white);
  border: 1px solid var(--gray-100);
}

.step-card .step-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--green-pale);
  color: var(--green-primary);
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 16px;
}

.step-card h3 {
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.step-card p {
  color: var(--gray-500);
  font-size: 0.9rem;
}

/* Status Tiers */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.tier-card {
  border-radius: var(--radius-lg);
  border: 2px solid var(--gray-100);
  padding: 32px;
  text-align: center;
  transition: all 0.2s;
}

.tier-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.tier-card.featured {
  border-color: var(--green-primary);
  background: var(--green-pale);
}

.tier-card .tier-icon {
  font-size: 2.5rem;
  margin-bottom: 16px;
}

.tier-card h3 {
  font-family: var(--font-heading);
  margin-bottom: 4px;
}

.tier-card .tier-threshold {
  font-size: 0.9rem;
  color: var(--gray-500);
  margin-bottom: 16px;
}

.tier-card .tier-benefits {
  text-align: left;
}

.tier-card .tier-benefits li {
  padding: 6px 0;
  font-size: 0.9rem;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: 8px;
}

.tier-card .tier-benefits li i {
  color: var(--green-primary);
  font-size: 1.1rem;
}

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 24px;
  flex-wrap: wrap;
  background: var(--gray-50);
  padding: 4px;
  border-radius: var(--radius-full);
}

.tab-btn {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--gray-600);
  transition: all 0.2s;
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--green-primary);
  background: var(--green-pale);
}

.tab-btn.active {
  background: var(--green-primary);
  color: var(--white);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

.tab-content-card {
  background: var(--off-white);
  border-radius: var(--radius-xl);
  padding: 48px;
  border: 1px solid var(--gray-100);
  text-align: center;
}

.tab-content-card .star-count {
  font-family: var(--font-heading);
  font-size: 3rem;
  color: var(--green-primary);
  margin-bottom: 8px;
}

.tab-content-card .reward-name {
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.tab-content-card .reward-value {
  color: var(--gray-500);
  font-size: 1rem;
}

/* Partnerships */
.partnerships {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.partner-card {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 24px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
}

.partner-icon {
  font-size: 2.5rem;
  color: var(--green-primary);
  flex-shrink: 0;
}

.partner-info p {
  font-size: 0.9rem;
  color: var(--gray-500);
}

/* ===== Gift Cards ===== */
.gift-hero {
  background: linear-gradient(135deg, var(--cream-light), var(--green-pale));
  border-radius: var(--radius-xl);
  padding: 64px;
  text-align: center;
  margin-bottom: 48px;
}

.gift-hero h1 {
  color: var(--green-dark);
  margin-bottom: 16px;
}

.gift-hero p {
  color: var(--gray-600);
  font-size: 1.1rem;
  max-width: 560px;
  margin: 0 auto 24px;
}

.carousel-section {
  margin-bottom: 48px;
}

.carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.carousel-header h2 {
  font-size: 1.5rem;
}

.carousel-controls {
  display: flex;
  gap: 8px;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  border: 2px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  transition: all 0.2s;
  font-size: 1.1rem;
}

.carousel-btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
  background: var(--green-pale);
}

.carousel-track-wrapper {
  overflow: hidden;
  border-radius: var(--radius-lg);
}

.carousel-track {
  display: flex;
  gap: 16px;
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.gift-card-item {
  flex: 0 0 calc(25% - 12px);
  min-width: 200px;
  aspect-ratio: 3/4;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, var(--gray-50), var(--gray-100));
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
  cursor: pointer;
  transition: all 0.2s;
  border: 2px solid transparent;
}

.gift-card-item:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.gift-card-item i {
  font-size: 2.5rem;
  margin-bottom: 12px;
  color: var(--green-primary);
}

.gift-card-item .card-name {
  font-weight: 600;
  font-size: 0.95rem;
  margin-bottom: 4px;
}

.gift-card-item .card-price {
  font-size: 0.85rem;
  color: var(--gray-500);
}

/* Business Gifting */
.business-gifting {
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  padding: 64px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.business-gifting h2 {
  color: var(--green-dark);
  margin-bottom: 12px;
}

.business-gifting p {
  color: var(--gray-600);
  margin-bottom: 24px;
}

.business-gifting-image {
  aspect-ratio: 4/3;
