}

/* FAQ */
.faq-list {
  max-width: 700px;
}

.faq-item {
  border-bottom: 1px solid var(--gray-100);
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 20px 0;
  font-weight: 600;
  font-size: 1rem;
  color: var(--gray-800);
