.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 20px;
  color: var(--gray-500);
  font-size: 0.9rem;
}

/* ===== Store Locator ===== */
.locator-layout {
  display: grid;
  grid-template-columns: 400px 1fr;
  gap: 24px;
  min-height: 600px;
}

.locator-sidebar {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.order-type-toggle {
  display: flex;
  background: var(--gray-50);
  border-radius: var(--radius-full);
  padding: 4px;
}

.order-type-toggle button {
  flex: 1;
  padding: 12px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--gray-600);
