}

.search-suggestions.open {
  display: block;
}

.search-suggestions li {
  padding: 12px 16px;
  cursor: pointer;
  font-size: 0.9rem;
  color: var(--gray-700);
}

.search-suggestions li:hover {
  background: var(--green-pale);
}

.filter-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--gray-600);
  transition: all 0.2s;
}

.filter-btn:hover,
.filter-btn.active {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.filter-panel {
  display: none;
