}

.filter-option input[type="checkbox"] {
  accent-color: var(--green-primary);
  width: 16px;
  height: 16px;
}

.map-container {
  background: var(--gray-100);
  border-radius: var(--radius-lg);
  min-height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 1.1rem;
  position: relative;
  overflow: hidden;
}

.map-placeholder {
  text-align: center;
  padding: 40px;
}

.map-placeholder i {
  font-size: 3rem;
  margin-bottom: 12px;
  display: block;
}

.store-results {
