  flex-direction: column;
  gap: 12px;
  max-height: 400px;
  overflow-y: auto;
}

.store-card {
  display: flex;
  gap: 16px;
  padding: 16px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  cursor: pointer;
  transition: all 0.2s;
}

.store-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-md);
}

.store-card.selected {
  border-color: var(--green-primary);
  background: var(--green-pale);
}

.store-card .store-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--green-pale);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green-primary);
  font-size: 1.5rem;
  flex-shrink: 0;
}

.store-info h4 {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 0.95rem;
  margin-bottom: 2px;
}

.store-info p {
  font-size: 0.8rem;
  color: var(--gray-500);
  line-height: 1.4;
}

.store-features {
  display: flex;
  gap: 8px;
  margin-top: 6px;
  flex-wrap: wrap;
}

.store-feature {
  font-size: 0.7rem;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  background: var(--green-pale);
  color: var(--green-primary);
  font-weight: 600;
}

/* ===== Cookie Banner ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  border-top: 1px solid var(--gray-100);
  padding: 20px 0;
  z-index: 200;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.08);
  transition: transform 0.3s ease;
}

.cookie-banner.hidden {
  transform: translateY(100%);
}

.cookie-banner .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-banner h4 {
  font-family: var(--font-body);
  margin-bottom: 2px;
}

.cookie-banner p {
  font-size: 0.85rem;
  color: var(--gray-500);
