}

/* ===== Terms ===== */
.terms-section {
  max-width: 800px;
  margin: 0 auto;
}

.terms-section h3 {
  font-family: var(--font-body);
  font-size: 1rem;
  margin-bottom: 8px;
  margin-top: 24px;
}

.terms-section p {
  font-size: 0.85rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== Kitchen Sink Icons (placeholder) ===== */
.icon-placeholder {
  opacity: 0.5;
}

/* ===== Animations ===== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  animation: fadeIn 0.5s ease forwards;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero .container {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-image {
    display: none;
  }

  .featured-card {
    grid-template-columns: 1fr;
  }

  .featured-card-content {
    padding: 32px;
  }

  .featured-card-image {
    display: none;
  }

  .seasonal-highlight {
    grid-template-columns: 1fr;
  }

  .promo-grid {
    grid-template-columns: 1fr;
  }

  .locator-layout {
    grid-template-columns: 1fr;
  }

  .map-container {
    min-height: 300px;
  }

  .business-gifting {
    grid-template-columns: 1fr;
  }

  .business-gifting-image {
    display: none;
  }

  .tiers-grid {
    grid-template-columns: 1fr;
  }

  .steps-grid {
    grid-template-columns: 1fr;
  }

  .partnerships {
    grid-template-columns: 1fr;
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .carousel-track .gift-card-item {
    flex: 0 0 calc(33.333% - 11px);
  }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-actions {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid var(--gray-700);
  }

  .footer-col h4 {
    cursor: pointer;
    padding: 16px 0;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    user-select: none;
  }

  .footer-col h4::after {
    content: '\ea4e';
    font-family: 'remixicon';
    font-size: 1.2rem;
    transition: transform 0.3s;
  }

  .footer-col.open h4::after {
    transform: rotate(180deg);
  }

  .footer-col .footer-links {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-col.open .footer-links {
    max-height: 400px;
    padding-bottom: 16px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .footer-bottom-links {
    flex-wrap: wrap;
    justify-content: center;
  }

  .cookie-banner .container {
    flex-direction: column;
    text-align: center;
  }

  .cookie-actions {
    flex-direction: column;
    width: 100%;
    max-width: 300px;
  }

  .cookie-actions .btn {
    width: 100%;
    justify-content: center;
  }

  .section {
    padding: 48px 0;
  }

  .hero {
    padding: 60px 0;
    min-height: auto;
  }

  .gift-hero {
    padding: 40px 24px;
  }

  .business-gifting {
    padding: 32px 24px;
  }

  .carousel-track .gift-card-item {
    flex: 0 0 calc(50% - 8px);
  }

  .store-results {
    max-height: none;
  }
}

@media (max-width: 480px) {
  .carousel-track .gift-card-item {
    flex: 0 0 calc(80% - 4px);
  }

  .redemption-tabs {
    flex-direction: column;
    background: none;
    gap: 8px;
  }

  .tab-btn {
    text-align: center;
    border: 2px solid var(--gray-200);
    border-radius: var(--radius-full);
  }

  .tab-btn.active {
    border-color: var(--green-primary);
  }

  .order-type-toggle {
    flex-direction: column;
    background: none;
    gap: 8px;
  }

  .order-type-toggle button {
    border: 2px solid var(--gray-200);
    border-radius: var(--radius-full);
  }

  .order-type-toggle button.active {
    border-color: var(--green-primary);
  }
}

